import { Badge, Card, cn } from '@gntik-ai/ui';
import { LineChart } from '@gntik-ai/charts';
import { formatMoney } from '../format';
import { sampleBudget, sampleSpend } from './fixtures';

export interface SpendPoint {
  /** X-axis label, e.g. "May 12". */
  label: string;
  /** Cumulative actual spend; null after today. */
  spend: number | null;
  /** Cumulative forecast; null before today. Start it on the last actual point to join the lines. */
  forecast?: number | null;
}

export interface SpendVsBudgetProps {
  data?: SpendPoint[];
  /** Budget cap for the period (drawn as a flat line). */
  budget?: number;
  currency?: string;
  title?: string;
  /** Period caption, e.g. "May cycle". */
  period?: string;
  /** Chart plot height in px. */
  height?: number;
  /** Heading level of the title, to fit the page outline (default h3). */
  titleAs?: 'h2' | 'h3' | 'h4';
  className?: string;
}

interface ChartRow {
  day: string;
  Spend: number | null;
  Forecast: number | null;
  Budget: number;
}

function lastValue(values: Array<number | null | undefined>): number | undefined {
  for (let i = values.length - 1; i >= 0; i--) {
    const v = values[i];
    if (v != null) return v;
  }
  return undefined;
}

/** Cumulative spend against a budget cap, with the end-of-period forecast. */
export function SpendVsBudget({
  data = sampleSpend,
  budget = sampleBudget,
  currency = 'USD',
  title = 'Spend vs budget',
  period = 'May cycle',
  height = 240,
  titleAs: TitleTag = 'h3',
  className,
}: SpendVsBudgetProps) {
  const toDate = lastValue(data.map((d) => d.spend)) ?? 0;
  const forecast = lastValue(data.map((d) => d.forecast)) ?? toDate;
  const over = forecast > budget;
  const rows: ChartRow[] = data.map((d) => ({ day: d.label, Spend: d.spend, Forecast: d.forecast ?? null, Budget: budget }));
  const money = (n: number) => formatMoney(n, currency, true);
  const stats = [
    { label: 'Spend to date', value: formatMoney(toDate, currency) },
    { label: 'Forecast', value: formatMoney(forecast, currency) },
    { label: 'Budget', value: formatMoney(budget, currency) },
  ];

  return (
    <Card className={cn('p-6', className)}>
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <TitleTag className="text-[15px] font-semibold tracking-tight text-foreground">{title}</TitleTag>
          {period && <p className="mt-0.5 text-[12.5px] text-muted-foreground">{period}</p>}
        </div>
        <Badge tone={over ? 'warning' : 'success'} dot>
          {over ? 'Forecast over budget' : 'Within budget'}
        </Badge>
      </div>
      <dl className="mt-4 grid grid-cols-3 gap-4">
        {stats.map((s) => (
          <div key={s.label} className="min-w-0">
            <dt className="text-[11.5px] text-muted-foreground">{s.label}</dt>
            <dd className="mt-1 truncate font-mono text-[14px] font-semibold text-foreground tabular-nums">{s.value}</dd>
          </div>
        ))}
      </dl>
      <LineChart
        className="mt-5"
        data={rows}
        index="day"
        categories={['Spend', 'Forecast', 'Budget']}
        colors={['primary', 'cyan', 'amber']}
        valueFormatter={money}
        height={height}
        aria-label={`${title}: ${formatMoney(toDate, currency)} spent, ${formatMoney(forecast, currency)} forecast against a ${formatMoney(budget, currency)} budget`}
      />
    </Card>
  );
}

import type { SpendPoint } from './SpendVsBudget';

/**
 * Sample cumulative spend for a 30-day cycle: actuals through day 18, forecast after.
 * The forecast starts on the last actual point so the two lines join.
 */
export const sampleSpend: SpendPoint[] = Array.from({ length: 30 }, (_, i) => {
  const day = i + 1;
  const actual = Math.round(day * 64 + Math.sin(day / 2) * 22);
  const lastActual = 18 * 64 + Math.round(Math.sin(9) * 22);
  return {
    label: `May ${day}`,
    spend: day <= 18 ? actual : null,
    forecast: day >= 18 ? Math.round(lastActual + (day - 18) * 46) : null,
  };
});

export const sampleBudget = 2000;

/** Shared formatting for the billing blocks (en-US, Intl). */

/** A calendar date: a `Date` or an ISO `YYYY-MM-DD` string (read as a local date, no UTC shift). */
export type DateInput = Date | string;

export function toDate(value: DateInput): Date {
  if (value instanceof Date) return value;
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (m) return new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  return new Date(value);
}

const dateFmt = new Intl.DateTimeFormat('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
const shortDateFmt = new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', year: 'numeric' });

/** "June 1, 2026". */
export function formatDate(value: DateInput): string {
  return dateFmt.format(toDate(value));
}

/** "Jun 1, 2026". */
export function formatShortDate(value: DateInput): string {
  return shortDateFmt.format(toDate(value));
}

/** Money with the currency symbol: "$1,620.00" (or no decimals with `whole`). */
export function formatMoney(amount: number, currency = 'USD', whole = false): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
    minimumFractionDigits: whole ? 0 : 2,
    maximumFractionDigits: whole ? 0 : 2,
  }).format(amount);
}

/** Grouped number, compact above a million: "412,800", "78.4M". */
export function formatQuantity(value: number): string {
  if (Math.abs(value) >= 1_000_000) {
    return new Intl.NumberFormat('en-US', { notation: 'compact', maximumFractionDigits: 1 }).format(value);
  }
  return new Intl.NumberFormat('en-US', { maximumFractionDigits: 1 }).format(value);
}
